full\",\"width\":{\"unit\":\"%\",\"size\":70},\"background_background\":\"classic\",\"background_image\":{\"url\":\"http:\\/\\/localhost\\/S_A_calma\\/wp-content\\/uploads\\/2026\\/05\\/fondo3.png\",\"id\":243,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"background_position\":\"center center\",\"background_size\":\"cover\"},\"elements\":[],\"isInner\":true},{\"id\":\"1cd8e74\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":30},\"padding\":{\"unit\":\"px\",\"top\":0,\"right\":0,\"bottom\":0,\"left\":0,\"isLinked\":true},\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"}},\"elements\":[{\"id\":\"d7aee46\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"background_background\":\"classic\",\"background_image\":{\"url\":\"http:\\/\\/localhost\\/S_A_calma\\/wp-content\\/uploads\\/2026\\/05\\/Detalle-Chimenea.png\",\"id\":229,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"background_position\":\"center center\",\"background_size\":\"cover\"},\"elements\":[],\"isInner\":true},{\"id\":\"60dcdd5\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\"},\"elements\":[{\"id\":\"ef1c9bb\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/S_A_calma\\/wp-content\\/uploads\\/2026\\/05\\/Detalle-Salo\\u0301n-1.png\",\"id\":230,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"medium\"},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false},{\"id\":\"8279369\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"flex_justify_content\":\"flex-end\",\"flex_align_items\":\"flex-end\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"50\",\"bottom\":\"150\",\"left\":\"50\",\"isLinked\":false}},\"elements\":[{\"id\":\"cd4f5a9\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_justify_content\":\"flex-start\",\"flex_align_items\":\"f