iner\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"},\"padding\":{\"unit\":\"px\",\"top\":0,\"right\":0,\"bottom\":0,\"left\":0,\"isLinked\":true},\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"}},\"elements\":[{\"id\":\"7c80f09\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\"},\"elements\":[{\"id\":\"e5cc806\",\"elType\":\"widget\",\"settings\":{\"image_size\":\"thumbnail\"},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true},{\"id\":\"c6a9bbe\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\"},\"elements\":[{\"id\":\"86876cf\",\"elType\":\"widget\",\"settings\":[],\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false},{\"id\":\"c8de155\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"150\",\"right\":\"50\",\"bottom\":\"150\",\"left\":\"50\",\"isLinked\":false},\"background_background\":\"classic\",\"background_image\":{\"url\":\"http:\\/\\/localhost\\/S_A_calma\\/wp-content\\/uploads\\/2026\\/05\\/Fondos_TEXTURAS_WEB_2.png\",\"id\":275,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"background_size\":\"cover\",\"__globals__\":{\"background_color\":\"\"}},\"elements\":[{\"id\":\"863a9fb\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>M\\u00c1S ALL\\u00c1 DE SU EST\\u00c9TICA, SA CALMA INTEGRA SOLUCIONES SOSTENIBLES<br \\/>QUE OPTIMIZAN RECURSOS Y REDUCEN EL IMPACTO AMBIENTAL, COMO LA<br \\/>GESTI\\u00d3N EFICIENTE DEL AGUA, EL USO DE MATERIALES LOCALES Y LA<br \\/>PRESERVACI\\u00d3N DE LA VEGETACI\\u00d3N AUT\\u00d3CTONA, HACIENDO DE LA<br \\/>SOSTENIBILIDAD UNA PARTE ESENCIAL DEL PROYECTO.<\\/p>\",\"align\":\"center\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false},{\"id\":\"122546d\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_wrap\":\"wrap\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":