\",\"source\":\"library\"},\"background_size\":\"cover\"},\"elements\":[],\"isInner\":true}],\"isInner\":false},{\"id\":\"793f4c8\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_wrap\":\"wrap\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"},\"background_background\":\"classic\",\"__globals__\":{\"background_color\":\"globals\\/colors?id=88bc9b2\"},\"z_index\":10},\"elements\":[{\"id\":\"1424faa\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":100}},\"elements\":[{\"id\":\"f9a8dd5\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Primer piso<\\/p>\",\"__globals__\":{\"typography_typography\":\"\",\"text_color\":\"globals\\/colors?id=a23def7\"},\"typography_typography\":\"custom\",\"typography_font_family\":\"Quattrocento\",\"typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":14,\"sizes\":[]},\"typography_font_weight\":\"400\",\"text_color\":\"#8F7548\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"bfb7407\",\"elType\":\"widget\",\"settings\":{\"title\":\"INTIMIDAD Y HORIZONTE\",\"header_size\":\"h1\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=a23def7\",\"typography_typography\":\"\"},\"typography_typography\":\"custom\",\"typography_font_family\":\"Marcellus\",\"typography_font_size\":{\"unit\":\"px\",\"size\":40,\"sizes\":[]},\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":25,\"sizes\":[]},\"typography_font_weight\":\"400\",\"typography_text_transform\":\"uppercase\",\"typography_line_height\":{\"unit\":\"px\",\"size\":100,\"sizes\":[]},\"title_color\":\"#8F7548\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"31d51cf\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\"},\"elements\":[{\"id\":\"2e730c8\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",